#include <stdio.h>
#include <stdlib.h>

#define MAXN 50005

int N;
int head[MAXN], to[2 * MAXN], nxt[2 * MAXN], ecnt;
int dist[MAXN], parentArr[MAXN], queueArr[MAXN];
int path[MAXN];
int stNode[MAXN], stParent[MAXN], stDepth[MAXN];

void addEdge(int u, int v) {
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt++;
}

int bfs(int src, int *par) {
    for (int i = 1; i <= N; i++) dist[i] = -1;

    int qh = 0, qt = 0;
    queueArr[qt++] = src;
    dist[src] = 0;
    if (par) par[src] = 0;

    int far = src;

    while (qh < qt) {
        int u = queueArr[qh++];

        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];

            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (par) par[v] = u;
                queueArr[qt++] = v;
            }
        }
    }

    return far;
}

long long countExact(int start, int blocked, int startDepth, int target) {
    if (startDepth > target) return 0;

    int top = 0;
    stNode[top] = start;
    stParent[top] = blocked;
    stDepth[top] = startDepth;
    top++;

    long long cnt = 0;

    while (top > 0) {
        top--;

        int u = stNode[top];
        int p = stParent[top];
        int d = stDepth[top];

        if (d == target) {
            cnt++;
            continue;
        }

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];

            if (v == p) continue;

            stNode[top] = v;
            stParent[top] = u;
            stDepth[top] = d + 1;
            top++;
        }
    }

    return cnt;
}

int main() {
    scanf("%d", &N);

    for (int i = 1; i <= N; i++) head[i] = -1;

    for (int i = 0; i < N - 1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);

        addEdge(x, y);
        addEdge(y, x);
    }

    int a = bfs(1, NULL);
    int b = bfs(a, parentArr);

    int D = dist[b];

    int cur = b;
    for (int i = D; i >= 0; i--) {
        path[i] = cur;
        cur = parentArr[cur];
    }

    long long ans = 0;

    if (D % 2 == 0) {
        int center = path[D / 2];
        int R = D / 2;

        long long total = 0;
        long long sumSq = 0;

        for (int e = head[center]; e != -1; e = nxt[e]) {
            int v = to[e];

            long long cnt = countExact(v, center, 1, R);

            total += cnt;
            sumSq += cnt * cnt;
        }

        ans = (total * total - sumSq) / 2;
    } else {
        int u = path[D / 2];
        int v = path[D / 2 + 1];
        int R = D / 2;

        long long cu = countExact(u, v, 0, R);
        long long cv = countExact(v, u, 0, R);

        ans = cu * cv;
    }

    printf("%d\n", D + 1);
    printf("%lld\n", ans);

    return 0;
}
